// CMD: just run-nn mbpo
// Model-based policy optimization (MBPO).
//
// Port of tflow's mbpo. Janner et al. 2019 train an ordinary off-policy agent
// (SAC) mostly on *imagined* data: short rollouts (k steps) branched from
// real states and generated by a probabilistic ensemble, so that model error
// cannot compound over long horizons. The model is refit periodically on all
// real data; the agent takes several gradient steps per environment step on a
// mixture of real and model-generated transitions.
//
// The TF graph becomes eager nn code: SAC as in the sac port (critic step,
// then actor + temperature from one forward pass, then Polyak), the ensemble
// is common/rl/dynamics_model.hpp (port of tflow's dynamics_model.h). The
// loop, Pendulum, replay sampling, model rollouts and every noise draw use
// the same std::mt19937_64 stream as TF; weights use nn's generator, so
// returns match TF statistically. The vsim video is replaced by
// PlayBestOfSeeds (same episode, printed, no video). Options as tflow's
// (steps=, warmup=, batch=, lr=, hidden=, seed=, log_every=, eval_every=, ...)
// plus threads=N. The port adds checks (exit 1 on failure).

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <datamunge/nn/nn.hpp>
#include <random>
#include <vector>

#include "common/checks.hpp"
#include "common/rl/classic_control.hpp"
#include "common/rl/continuous.hpp"
#include "common/rl/dynamics_model.hpp"
#include "common/rl/play_best.hpp"
#include "common/rl/replay.hpp"

namespace nn = datamunge::nn;
using nn::Tensor;

int main(int argc, char** argv) {
  try {
    rl::CConfig cfg;
    cfg.steps = 8000;
    cfg.warmup = 500;
    cfg.actor_lr = cfg.critic_lr = 3e-4f;
    cfg.log_every = 1000;
    cfg.eval_every = 2000;
    rl::ParseCConfig(argc, argv, &cfg);
    const int members = 5, model_every = 250, model_steps = example_runtime::Limit(200, 8), rollouts_per_step = example_runtime::Limit(50, 4), max_horizon = 5, updates_per_step = example_runtime::Limit(5, 1);
    const float real_ratio = 0.1f;
    rl::Pendulum env, eval_env;
    const rl::ActionSpace space = env.action_space();
    const int obs_dim = env.obs_size(), act_dim = space.dim;
    std::printf("== MBPO on Pendulum: %d real steps, %d-member ensemble refit every %d steps, %d model rollouts (k up to %d) per step, "
                "%d SAC updates per step on %.0f%% model data\n",
                cfg.steps, members, model_every, rollouts_per_step, max_horizon, updates_per_step, 100 * (1 - real_ratio));

    rl::DynamicsEnsemble model(members, obs_dim, act_dim, 128, 1e-3f, 100);
    // ---- SAC (as in 6.5/sac)
    nn::ParameterStore actor(cfg.seed), critic(cfg.seed + 1), critic_t(cfg.seed + 2), temperature(cfg.seed + 3);
    const Tensor log_alpha = temperature.get("log_alpha", {}, nn::init::zeros());
    auto policy = [&](const Tensor& s) { return rl::GaussianActor(actor, "pi", s, act_dim, cfg.hidden); };
    auto q = [&](nn::ParameterStore& p, const char* name, const Tensor& s, const Tensor& a) { return rl::QNetwork(p, name, s, a, cfg.hidden); };
    {
      nn::NoGradGuard no_grad;
      const Tensor s0 = nn::zeros({1, obs_dim}), a0 = nn::zeros({1, act_dim});
      policy(s0);
      for (nn::ParameterStore* p : {&critic, &critic_t}) q(*p, "q1", s0, a0), q(*p, "q2", s0, a0);
    }
    rl::Adam critic_adam(critic, cfg.critic_lr), actor_adam(actor, cfg.actor_lr), alpha_adam(temperature, cfg.actor_lr);
    critic_t.copy_from(critic, 1.0);

    rl::ReplayBuffer real_buffer(cfg.buffer, obs_dim), model_buffer(200000, obs_dim);
    rl::TransitionSet data;
    rl::Monitor monitor(rl::MonitorConfig(cfg), "model mse");
    std::mt19937_64 rng(cfg.seed);
    auto act_stochastic = [&](const rl::Obs& o) {
      nn::NoGradGuard no_grad;
      return rl::SquashedSample(policy(rl::Row(o)), rl::NormalNoise(1, act_dim, rng)).action.to_vector<float>();
    };
    auto act_mean = [&](const rl::Obs& o) {
      nn::NoGradGuard no_grad;
      return nn::tanh(policy(rl::Row(o)).mean).to_vector<float>();
    };
    auto sac_update = [&](const rl::Batch& b) {
      const int n = static_cast<int>(b.r.shape()[0]);
      const Tensor eps = rl::NormalNoise(n, act_dim, rng), eps2 = rl::NormalNoise(n, act_dim, rng);
      const Tensor alpha = nn::exp(log_alpha);
      Tensor y;
      {
        nn::NoGradGuard no_grad;
        const rl::Squashed next = rl::SquashedSample(policy(b.s2), eps2);
        const Tensor soft_next = nn::minimum(q(critic_t, "q1", b.s2, next.action), q(critic_t, "q2", b.s2, next.action)) - alpha.detach() * next.logp;
        y = b.r + (cfg.gamma * (1.0 - b.done)) * soft_next;
      }
      const Tensor critic_loss = nn::mean(nn::square(y - q(critic, "q1", b.s, b.act_c)), {0}) +
                                 nn::mean(nn::square(y - q(critic, "q2", b.s, b.act_c)), {0});
      critic_adam.Minimize(critic_loss);
      const float cl = critic_loss.item<float>();
      check::Require(std::isfinite(cl), "finite critic loss");
      monitor.AddLoss(cl);
      const rl::Squashed sample = rl::SquashedSample(policy(b.s), eps);
      const Tensor actor_loss = nn::mean(alpha.detach() * sample.logp - nn::minimum(q(critic, "q1", b.s, sample.action), q(critic, "q2", b.s, sample.action)), {0});
      const Tensor alpha_loss = -nn::mean(log_alpha * (sample.logp.detach() - static_cast<double>(act_dim)), {0});
      actor_adam.Minimize(actor_loss);
      alpha_adam.Minimize(alpha_loss);
      critic_t.copy_from(critic, cfg.tau);
    };
    // Combine a real and a model batch into one (real rows first).
    auto mixed_batch = [&](int n) {
      const int n_real = std::max(1, static_cast<int>(n * real_ratio));
      const rl::Batch br = real_buffer.Sample(n_real, rng), bm = model_buffer.Sample(n - n_real, rng);
      rl::Batch b;
      b.s = nn::concat({br.s, bm.s}, 0), b.s2 = nn::concat({br.s2, bm.s2}, 0), b.act_c = nn::concat({br.act_c, bm.act_c}, 0);
      b.r = nn::concat({br.r, bm.r}, 0), b.done = nn::concat({br.done, bm.done}, 0);
      return b;
    };

    rl::Obs obs = env.reset(cfg.seed);
    float ret = 0, model_mse = 0, first_mse = -1;
    for (int step = 1; step <= cfg.steps; ++step) {
      std::vector<float> u(act_dim);
      if (step <= cfg.warmup)
        for (float& x : u) x = std::uniform_real_distribution<float>(-1, 1)(rng);
      else
        u = act_stochastic(obs);
      rl::Action a_env = rl::ScaleAction(u, space);
      rl::StepResult sr = env.step(a_env);
      real_buffer.Add({obs, 0, sr.reward, sr.obs, sr.terminated ? 1.f : 0.f, u});
      data.Add(obs, a_env.continuous, sr.obs, sr.reward);
      ret += sr.reward;
      obs = sr.obs;
      if (sr.done()) monitor.EndEpisode(ret), ret = 0, obs = env.reset();
      if (step >= cfg.warmup) {
        // Refit the ensemble on all real data.
        if (step % model_every == 0 || step == cfg.warmup)
          for (int i = 0; i < model_steps; ++i) {
            Tensor S, A, S2, R;
            data.Sample(cfg.batch, rng, &S, &A, &S2, &R);
            model_mse = model.Train(S, A, S2, R).second;
            if (first_mse < 0) first_mse = model_mse;
          }
        // Branch short model rollouts from real states; the horizon grows with training.
        const int k = 1 + std::min(max_horizon - 1, (step - cfg.warmup) * max_horizon / cfg.steps);
        const rl::Batch starts = real_buffer.Sample(rollouts_per_step, rng);
        Tensor S = starts.s;
        for (int t = 0; t < k; ++t) {
          std::vector<float> U, A_env(static_cast<size_t>(rollouts_per_step) * act_dim);
          {
            nn::NoGradGuard no_grad;
            U = rl::SquashedSample(policy(S), rl::NormalNoise(rollouts_per_step, act_dim, rng)).action.to_vector<float>();
          }
          for (int i = 0; i < rollouts_per_step; ++i)
            for (int d = 0; d < act_dim; ++d) A_env[i * act_dim + d] = rl::ScaleAction({U[i * act_dim + d]}, space).continuous[d];
          const rl::DynamicsEnsemble::Prediction p =
              model.Predict(static_cast<int>(rng() % members), S, nn::from_vector(A_env, {rollouts_per_step, act_dim}), true, rng);
          const std::vector<float> sv = S.to_vector<float>(), nv = p.next_s.to_vector<float>(), rv = p.r.to_vector<float>();
          for (int i = 0; i < rollouts_per_step; ++i) {
            rl::Obs so(sv.begin() + i * obs_dim, sv.begin() + (i + 1) * obs_dim), sn(nv.begin() + i * obs_dim, nv.begin() + (i + 1) * obs_dim);
            std::vector<float> ua(U.begin() + i * act_dim, U.begin() + (i + 1) * act_dim);
            model_buffer.Add({so, 0, rv[i], sn, 0.f, ua});  // Pendulum never terminates
          }
          S = p.next_s;
        }
        for (int u_i = 0; u_i < updates_per_step; ++u_i) sac_update(mixed_batch(cfg.batch));
      }
      if (step % cfg.log_every == 0)
        monitor.Log(step, model_mse, step % cfg.eval_every == 0 ? rl::EvaluateC(eval_env, act_mean, cfg.eval_episodes, 1000 + step) : NAN);
    }
    const float final_eval = rl::EvaluateC(eval_env, act_mean, 20, 777);
    std::printf("  final evaluation over 20 episodes (mean action): %.1f after only %d real steps (compare sac.cc at 20000)\n",
                final_eval, cfg.steps);
    // On film in TF: the mean action and the critics' min(Q1, Q2)(s, a), the return they expect from here.
    rl::PlayBestOfSeeds(eval_env, [&](const rl::Obs& o) {
      nn::NoGradGuard no_grad;
      const std::vector<float> u = act_mean(o);
      const Tensor s = rl::Row(o), a = nn::from_vector(u, {1, act_dim});
      const float v = std::min(q(critic, "q1", s, a).item<float>(), q(critic, "q2", s, a).item<float>());
      return rl::Explain(rl::ScaleAction(u, space), v, "min(Q1,Q2)(s,a)");
    }, "mbpo_pendulum", 4242);

    check::TrainingQuality(model_mse < first_mse, "the dynamics ensemble's error falls with refitting");
    if (cfg.steps >= 8000)
      check::TrainingQuality(final_eval >= -400, "MBPO learned to swing up in 8000 real steps (mean-action evaluation >= -400)");
    std::printf("\nchecks passed (vsim video omitted)\n");
  } catch (const std::exception& e) {
    std::fprintf(stderr, "CHECK FAILED: %s\n", e.what());
    return 1;
  }
  return 0;
}
